import { ref, onMounted } from "vue";
import { useRoute } from "vue-router";
export default {
  __name: 'ProductPage',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const route = useRoute(); // 获取当前路由参数
    const product = ref({}); // 存储商品信息

    // 获取商品详细信息
    onMounted(async () => {
      const productId = route.params.id; // 从路由参数获取商品 ID
      const response = await fetch(`/api/products/${productId}`); // 请求商品详情 API
      if (response.ok) {
        product.value = await response.json(); // 将获取到的商品信息存储
      } else {
        console.error("获取商品详情失败");
      }
    });
    const addToCart = () => {
      alert(`${product.value.title} 已加入购物车！`); // 模拟加入购物车
    };
    const __returned__ = {
      route,
      product,
      addToCart,
      ref,
      onMounted,
      get useRoute() {
        return useRoute;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
